import React, { useState, useRef } from "react";
import { useNavigate } from "react-router-dom";
import MoonLoader from "react-spinners/MoonLoader";
import axios from "axios";
import "./Upload.css";

function Upload() {
  const [videoFile, setVideoFile] = useState(null);
  const [rubricFile, setRubricFile] = useState(null);
  const [rubricFileName, setRubricFileName] = useState("");
  const [transcript, setTranscript] = useState("");
  const [feedback, setFeedback] = useState("");
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState("");
  const [analysis, setAnalysis] = useState({});

  const navigate = useNavigate();
  const rubricInputRef = useRef(null);

  // Accept .txt, .csv, .json
  const handleRubricUpload = (event) => {
    const file = event.target.files[0];
    if (
      file &&
      (file.type === "text/plain" ||
        file.type === "application/json" ||
        file.type === "text/csv" ||
        file.name.endsWith(".txt") ||
        file.name.endsWith(".csv") ||
        file.name.endsWith(".json"))
    ) {
      setRubricFile(file);
      setRubricFileName(file.name);
    } else {
      alert("Please upload a valid rubric file (.txt, .csv, .json).");
    }
  };

  const handleFileChange = (event) => {
    setVideoFile(event.target.files[0]);
  };

  const handleAnalyze = async () => {
    const userId = localStorage.getItem("user_id");
    if (!userId) {
      alert("You must be logged in to upload and analyze videos.");
      navigate("/login");
      return;
    }
    if (!videoFile) {
      alert("Please upload a video before analyzing.");
      return;
    }

    setStatus("processing");
    setLoading(true);

    // 1. Send video to /transcribe
    const formData = new FormData();
    formData.append("video", videoFile);

    let transcribeData;
    try {
      const response = await axios.post(
        "http://34.55.142.231:5000/transcribe",
        formData,
        { headers: { "Content-Type": "multipart/form-data" } }
      );
      transcribeData = response.data;
      setTranscript(transcribeData.transcript);
      setAnalysis(transcribeData);
    } catch (error) {
      setStatus("");
      setLoading(false);
      alert("Error processing video. Please try again.");
      return;
    }

    // 2. If rubric is provided, send to /evaluate
    if (rubricFile) {
      const evalForm = new FormData();
      evalForm.append("rubric", rubricFile);
      evalForm.append("transcript", transcribeData.transcript);
      evalForm.append("speech_rate", transcribeData.speech_rate_wps);
      evalForm.append("num_pauses", transcribeData.num_pauses);
      evalForm.append("total_silence", transcribeData.total_silence_sec);
      evalForm.append("avg_pitch", transcribeData.average_pitch);
      evalForm.append(
        "emotion_summary",
        JSON.stringify(transcribeData.emotion_summary)
      );
      evalForm.append("eye_contact_ratio", transcribeData.eye_contact_ratio);

      try {
        const evalResponse = await axios.post(
          "http://34.55.142.231:5000/evaluate",
          evalForm,
          { headers: { "Content-Type": "multipart/form-data" } }
        );
        setFeedback(evalResponse.data.evaluation);
      } catch (error) {
        setFeedback("Error with rubric evaluation.");
      }
    } else {
      setFeedback(transcribeData.ai_feedback);
    }

    // 3. Save video and feedback
    try {
      await axios.post("http://34.55.142.231:5000/save-video", {
        user_id: userId,
        video_filename: transcribeData.video_filename,
        feedback: rubricFile ? feedback : transcribeData.ai_feedback,
      });
    } catch (error) {
      // Handle save error (optional)
    }

    setStatus("");
    setLoading(false);
    navigate("/library");
  };

  return (
    <div className="dashboard-container">
      <h1 className="page-title">Video Analysis Dashboard</h1>

      {status === "processing" ? (
        <div className="dashboard-content">
          <div className="loader-div">
            <MoonLoader size={50} color="#77232C" />
          </div>
        </div>
      ) : (
        <div className="upload-content">
          <div className="upload-div">
            {videoFile ? (
              <video controls>
                <source src={URL.createObjectURL(videoFile)} type={videoFile.type} />
                Your browser does not support the video tag.
              </video>
            ) : (
              <input type="file" accept="video/*" onChange={handleFileChange} />
            )}

            <button className="save-button" onClick={handleAnalyze} disabled={loading}>
              Analyze Video
            </button>

            <div style={{ marginTop: "10px" }}>
              <input
                ref={rubricInputRef}
                type="file"
                accept=".txt,.csv,.json"
                id="rubric-upload"
                onChange={handleRubricUpload}
                style={{ display: "none" }}
              />
              <button
                className="save-button"
                type="button"
                onClick={() => rubricInputRef.current && rubricInputRef.current.click()}
              >
                Upload Rubric
              </button>
            </div>

            {rubricFileName && (
              <p style={{ marginTop: "10px", color: "#77232C", fontWeight: "bold" }}>
                Uploaded Rubric: {rubricFileName}
              </p>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default Upload;
